// Returns a cached NexHealth bearer token when still valid (cached 50 min in workflow static data).
// Static data only persists for production (activated) executions; manual test runs re-authenticate.
const sd = $getWorkflowStaticData('global');
const valid = sd.nexhealthToken && sd.nexhealthTokenExpires && Number(sd.nexhealthTokenExpires) > Date.now();
return [{ json: { token: valid ? sd.nexhealthToken : null } }];

// POST https://nexhealth.info/authenticates responds { code, data: { token } }.
const sd = $getWorkflowStaticData('global');
const token = $json.data && $json.data.token;
if (!token) { throw new Error('NexHealth /authenticates returned no token'); }
sd.nexhealthToken = token;
sd.nexhealthTokenExpires = Date.now() + 50 * 60 * 1000;
return [{ json: { token } }];

// ---- shared helpers (duplicated in each workflow on purpose: n8n Code nodes cannot import) ----
const crypto = require('crypto');
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const SALT = $env.PATIENT_HASH_SALT || '';
const envJson = (k) => { try { return JSON.parse($env[k] || '{}'); } catch (e) { return {}; } };
const sha256 = (s) => crypto.createHash('sha256').update(String(s)).digest('hex');
const patientRef = (id) => (id === null || id === undefined || id === '') ? null : sha256(String(id) + SALT);
const fmt = (d, opts) => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: TZ }, opts)).format(d);
const ordinal = (n) => n + ((n % 10 === 1 && n !== 11) ? 'st' : (n % 10 === 2 && n !== 12) ? 'nd' : (n % 10 === 3 && n !== 13) ? 'rd' : 'th');
const sayWhen = (iso) => { const d = new Date(iso); return fmt(d, { weekday: 'long' }) + ' the ' + ordinal(Number(fmt(d, { day: 'numeric' }))) + ' at ' + fmt(d, { hour: 'numeric', minute: '2-digit' }); };
const providerFirst = (id, fallbackName) => {
  const names = envJson('NEXHEALTH_PROVIDER_NAMES');
  if (id !== null && id !== undefined && names[String(id)]) return names[String(id)];
  if (fallbackName) { const parts = String(fallbackName).replace(/^(dr\.?|doctor)\s+/i, '').trim().split(/\s+/); return parts.length ? 'Dr. ' + parts[parts.length - 1] : null; }
  return null;
};
const e164 = (p) => { if (!p) return null; let d = String(p).replace(/[^\d+]/g, ''); if (d.startsWith('+')) return d; d = d.replace(/\D/g, ''); if (d.length === 10) return '+1' + d; if (d.length === 11 && d.startsWith('1')) return '+' + d; return d ? '+' + d : null; };
// ---- end helpers ----

// Input args: { appointment_type: 'cleaning'|'exam'|'emergency'|'other', preference: 'morning'|'afternoon'|'any', provider_id?, start_date? }
const input = $('Sub-workflow trigger').first().json;
const args = input.args || {};
const types = envJson('NEXHEALTH_APPT_TYPE_IDS');   // { "cleaning": 11, "exam": 12, "emergency": 13, "other": 12 }
const typeKey = String(args.appointment_type || 'exam').toLowerCase();
const appointment_type_id = args.appointment_type_id || types[typeKey] || types.exam || types.other || null;
const provider_id = args.provider_id || null;
if (!appointment_type_id && !provider_id) throw new Error('get_slots needs appointment_type_id (NEXHEALTH_APPT_TYPE_IDS) or provider_id; NexHealth requires one of them');
const startDate = (() => {
  if (args.start_date) { const d = new Date(args.start_date); if (!isNaN(d) && d > new Date()) return d.toISOString().slice(0, 10); }
  return new Date(Date.now() + 24 * 3600 * 1000).toISOString().slice(0, 10);
})();
const q = new URLSearchParams();
q.set('subdomain', $env.NEXHEALTH_SUBDOMAIN || '');
q.append('lids[]', String(input.location_id || ''));
q.set('start_date', startDate);
q.set('days', '14');
if (appointment_type_id) q.set('appointment_type_id', String(appointment_type_id));
if (provider_id) q.append('pids[]', String(provider_id));
if (String($env.NEXHEALTH_OVERLAPPING_OPERATORY_SLOTS || 'false') === 'true') q.set('overlapping_operatory_slots', 'true');
return [{ json: { token: $json.token, url: 'https://nexhealth.info/available_slots?' + q.toString(), appointment_type_id, provider_id, preference: String(args.preference || 'any').toLowerCase(), call_id: input.call_id } }];

// ---- shared helpers (duplicated in each workflow on purpose: n8n Code nodes cannot import) ----
const crypto = require('crypto');
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const SALT = $env.PATIENT_HASH_SALT || '';
const envJson = (k) => { try { return JSON.parse($env[k] || '{}'); } catch (e) { return {}; } };
const sha256 = (s) => crypto.createHash('sha256').update(String(s)).digest('hex');
const patientRef = (id) => (id === null || id === undefined || id === '') ? null : sha256(String(id) + SALT);
const fmt = (d, opts) => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: TZ }, opts)).format(d);
const ordinal = (n) => n + ((n % 10 === 1 && n !== 11) ? 'st' : (n % 10 === 2 && n !== 12) ? 'nd' : (n % 10 === 3 && n !== 13) ? 'rd' : 'th');
const sayWhen = (iso) => { const d = new Date(iso); return fmt(d, { weekday: 'long' }) + ' the ' + ordinal(Number(fmt(d, { day: 'numeric' }))) + ' at ' + fmt(d, { hour: 'numeric', minute: '2-digit' }); };
const providerFirst = (id, fallbackName) => {
  const names = envJson('NEXHEALTH_PROVIDER_NAMES');
  if (id !== null && id !== undefined && names[String(id)]) return names[String(id)];
  if (fallbackName) { const parts = String(fallbackName).replace(/^(dr\.?|doctor)\s+/i, '').trim().split(/\s+/); return parts.length ? 'Dr. ' + parts[parts.length - 1] : null; }
  return null;
};
const e164 = (p) => { if (!p) return null; let d = String(p).replace(/[^\d+]/g, ''); if (d.startsWith('+')) return d; d = d.replace(/\D/g, ''); if (d.length === 10) return '+1' + d; if (d.length === 11 && d.startsWith('1')) return '+' + d; return d ? '+' + d : null; };
// ---- end helpers ----

// Response: { data: [ { lid, pid, operatory_id, slots: [ { time, end_time, operatory_id, provider_id } ] } ] }
const req = $('Build request').first().json;
const groups = Array.isArray($json.data) ? $json.data : [];
let slots = [];
for (const g of groups) for (const s of (g.slots || [])) {
  slots.push({ time: s.time, provider_id: s.provider_id || g.pid || req.provider_id || null, operatory_id: s.operatory_id || g.operatory_id || null });
}
slots = slots.filter(s => s.time && new Date(s.time) > new Date());
slots.sort((a, b) => new Date(a.time) - new Date(b.time));
const hourOf = (t) => Number(fmt(new Date(t), { hour: 'numeric', hour12: false })) % 24;
if (req.preference === 'morning') slots = slots.filter(s => hourOf(s.time) < 12);
else if (req.preference === 'afternoon') slots = slots.filter(s => hourOf(s.time) >= 12);
// Offer at most three, preferring different days so the caller hears distinct options.
const seen = new Set(); const picked = [];
for (const s of slots) { const day = fmt(new Date(s.time), { year: 'numeric', month: '2-digit', day: '2-digit' }); if (seen.has(day)) continue; seen.add(day); picked.push(s); if (picked.length === 3) break; }
for (const s of slots) { if (picked.length === 3) break; if (!picked.includes(s)) picked.push(s); }
// The slot id is self-describing ("<start>|<provider_id>|<operatory_id>|<appointment_type_id>") because n8n workflow
// static data is scoped per workflow and 04/05 cannot read a cache written here.
const out = picked.map(s => {
  const prov = providerFirst(s.provider_id);
  return { id: [s.time, s.provider_id || '', s.operatory_id || '', req.appointment_type_id || ''].join('|'), say: sayWhen(s.time) + (prov ? ' with ' + prov : '') };
});
if (!out.length) return [{ json: { status: 'no_slots', slots: [] } }];
return [{ json: { status: 'ok', slots: out } }];
